def migrar_autores_legados(apps, schema_editor):
    Autor = apps.get_model("acervo", "Autor")
    Livro = apps.get_model("acervo", "Livro")
    banco = schema_editor.connection.alias

    for livro in Livro.objects.using(banco).all().iterator():
        autor, _ = Autor.objects.using(banco).get_or_create(
            organizacao_id=livro.organizacao_id,
            nome=livro.autor_nome_legado,
            sobrenome="",
        )
        Livro.objects.using(banco).filter(pk=livro.pk).update(autor_id=autor.pk)


def restaurar_autores_legados(apps, schema_editor):
    Livro = apps.get_model("acervo", "Livro")
    banco = schema_editor.connection.alias

    for livro in Livro.objects.using(banco).select_related("autor").iterator():
        Livro.objects.using(banco).filter(pk=livro.pk).update(
            autor_nome_legado=livro.autor.nome
            if not livro.autor.sobrenome
            else f"{livro.autor.nome} {livro.autor.sobrenome}"
        )


